import React from "react";
import { motion } from "framer-motion";
import LandmarkIcons10km, { LandmarkIcon, landmarkIcons10km } from "../icons/LandmarkIcons10km";
import CustomTooltip from "@/components/atoms/CustomTooltip";

const COLORS = {
  background: "#0F172A",
  backgroundOpacity: "0.95",
  text: "#F8FAFC",
  routeStroke: "white",
  building: "#e2e8f0",
};

const STROKE_WIDTHS = {
  default: "5",
  thin: "3",
};

const DEFAULT_IMAGE = "/landmarks/gar.webp";

interface LandmarkProps {
  id: string;
  path: string;
  strokeWidth?: string;
  delay?: number;
}

interface LandmarkDetailsProps {
  icon: React.ReactNode;
  distance: string;
  time: string;
  landmark_name: string;
  details: string;
  img?: string;
}

interface AnimatedLandmarkIconProps {
  landmarkKey: string;
  delay?: number;
}

// Simple, smooth animated wrapper for landmark icons
const AnimatedLandmarkIcon: React.FC<AnimatedLandmarkIconProps> = ({
  landmarkKey,
  delay = 0
}) => {
  const landmarkData = landmarkIcons10km[landmarkKey];
  const tooltipContent = landmarkData?.label || landmarkKey;

  return (
    <motion.g
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95 }}
      transition={{
        duration: 0.6,
        delay: delay,
        ease: "easeOut"
      }}
      whileHover={{ scale: 1.05 }}
      style={{ transformOrigin: "center" }}
    >
      <CustomTooltip content={tooltipContent} placement="top">
        <LandmarkIcon landmarkKey={landmarkKey} />
      </CustomTooltip>
    </motion.g>
  );
};

const createLandmark = ({
  id,
  path,
  strokeWidth = STROKE_WIDTHS.default,
  delay = 0,
}: LandmarkProps) => (
  <motion.path
    id={`__route ${id}`}
    d={path}
    stroke={COLORS.routeStroke}
    strokeWidth={strokeWidth}
    fill="none"
    initial={{ pathLength: 0, opacity: 0 }}
    animate={{ pathLength: 1, opacity: 1 }}
    exit={{ pathLength: 0, opacity: 0 }}
    transition={{
      pathLength: { duration: 1.2, delay: delay + 0.4, ease: "easeInOut" },
      opacity: { duration: 0.4, delay: delay + 0.4, ease: "easeOut" }
    }}
  />
);

const createLandmarkDetails = ({
  icon,
  distance,
  time,
  landmark_name,
  details,
  img,
}: LandmarkDetailsProps) => ({
  icon,
  distance,
  time,
  landmark_name,
  details,
  img: img || DEFAULT_IMAGE,
});

